window.PARAGRAPH8_LGS_DENEME_QUESTIONS = [{"grade":8,"topic":"Parçada anlam","difficulty":"Orta","outcome":"Paragrafta anlam, yapı ve anlatım özelliklerini belirler.","text":"Ne kadar da fazla dizi ve film oynuyor televizyonda değil mi? Hangimiz bu dizi ve filmlerin hepsini izliyor acaba? Televizyonda yayınlanan diziler hiç de gerçeği yansıtmıyor. Bu diziler kendimizin ve toplumun ekonomik düzeyini yansıtmayıp halkımızın sorunlarına ve yaşam zorluklarına da değinmiyor. Gerçekten de gerçeklikten çok uzak. Bu dizi ve filmler hiçbir konu hakkında bir bilgi ya da öğüt de vermiyor üstelik. İzleyicilere bilgi vermek şöyle dursun onları sahte duruşlarıyla olumsuz etkiliyorlar. İzleyiciler ne yazık ki kendilerini diziye kaptırıyor ve adeta dizi başrol oyuncularını ilah gibi görüyorlar. Özetle onların hayatını benimsiyor ve onlar gibi yaşamaya çalışıyorlar. Bu tarz dizi ve filmlerin sayısı gün geçtikçe artmaktadır.","stem":"Aşağıdakilerden hangisi metinde yazarın yakındığı durumlardan biri değildir?","options":["Dizi ve filmlerin sayısının her geçen gün artması","Televizyondaki dizi ve filmlerin yeterince izlenmemesi","Dizilerin halkın gerçeklerini yansıtmaması","Dizilerin insanları olumsuz etkilemesi"],"answer":"B","solution":"Doğru cevap B seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Önce soru kökünü okuyup metindeki ilgili kanıtları belirleyiniz.","hint":"Seçenekleri metnin bütünüyle karşılaştırınız.","keepOptionOrder":true,"plainText":true,"collection":"grade8-lgs-deneme-expanded"},{"grade":8,"topic":"Parçada anlam","difficulty":"Orta","outcome":"Paragrafta anlam, yapı ve anlatım özelliklerini belirler.","text":"Doğruluğu ya da yanlışlığı kanıtlanamayan, kişiden kişiye değişen yargılara öznel yargı; doğruluğu ya da yanlışlığı kanıtlanabilen, kişiden kişiye değişmeyen yargılara da nesnel yargı denir.","stem":"Buna göre aşağıdaki metinlerden hangisi kanıtlanabilirlik açısından farklıdır?","options":["Eskiden su, bazı kentlere kilometrelerce uzakta bulunan tepelerdeki kaynaklardan getiriliyordu. Su kaynağının kentin bulunduğu yerden daha yüksek bir yerde olması gerekiyordu. Çünkü suyu kente taşımak için, hafif eğimli bir şekilde yapılan kanallar ve borular kullanılıyordu.","Mikrodalga fırınlar yiyecekleri ısıtmak için mikrodalgaları kullanır. Bu fırınlar, radar sistemleri üzerine çalışan Percy Spencer adlı bir bilim insanı tarafından 1945 yılında bulundu. Spencer, laboratuarda manyetron adı verilen mikrodalga üretmeye yarayan bir aygıtla çalışırken cebinde bulunan çikolatanın eridiğini fark etti.","İlk halının nerede ve ne zaman dokunduğu tarihçiler tarafından kesin olarak belirtilemese de ilk halı örneklerinin MÖ 500' lü yıllarda Anadolu, Türkmenistan, İran ve Çin' de üretildiği düşünülmektedir. Halıyı ilk kullananlar ise Orta Asya göçebe toplulukları olmuştur.","Endemik bitkilerin en çok yayılış gösterdiği ülkelerin başında Türkiye geliyor. Bunun da büyük bir bölümünü Karadeniz Bölgesi ve Artvin sınırları içerisinde kalan bölüm oluşturuluyor. Son yıllarda özellikle yabancı araştırmacıların ülkemize gelip bu çeşitleri kaçırmaya çalıştıklarına şahit oluyoruz. Ülke olarak bu konuda gerekli hassasiyeti gösterdiğimiz söylenemez."],"answer":"D","solution":"Doğru cevap D seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Önce soru kökünü okuyup metindeki ilgili kanıtları belirleyiniz.","hint":"Seçenekleri metnin bütünüyle karşılaştırınız.","keepOptionOrder":true,"plainText":true,"collection":"grade8-lgs-deneme-expanded"},{"grade":8,"topic":"Paragraf tamamlama","difficulty":"Orta","outcome":"Paragrafta anlam, yapı ve anlatım özelliklerini belirler.","text":"16. yüzyılda gemiyle keşiflere çıkan gemicilerin pek çoğu hayatlarını kaybederdi. Buradaki azılı düşman yerliler, düşman gemileri değil “iskorbüt” adı verilen bir hastalıktı. Hastalık ilerledikçe gemicilerin dişleri düşüyor, açık yaralar oluşuyor, ateşleri yükseliyor, ciltleri sararıyordu. Kimse bu hastalığa neyin yol açtığını bilmiyordu. Bunun beslenmeyle ilgili olacağını düşünenler vardı çünkü gemi yolculuklarında dayanıklı yiyecek malzemeleri olan kurutulmuş et, tahıl vb. kullanılırdı. 1727’de James Lind yaptığı deneylerde bu hastalığın tedavi yöntemini bulmuştu. Narenciye tüketmek. Uzun yolculuklarda meyve ve sebze tüketilmemesinin bu hastalığa davetiye çıkardığı anlaşılınca Bu parçanın sonuna anlam akışına göre","stem":"aşağıdakilerden hangisi getirilmelidir?","options":["deney yaparak insan hayatını kurtarmanın doğru bir yol olduğunu anladılar.","Kaptanlar, James Lind’in gemilerle seyahat ederek bu hastalığı izlemesini istediler.","dünyanın bütün kaptanları bu beslenme yöntemini kullanarak sayısız denizcinin hayatını kurtardılar.","denizlerdeki gemi sayısı hızla artmış ve yeni yerler keşfedilmiştir."],"answer":"C","solution":"Doğru cevap C seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Önce soru kökünü okuyup metindeki ilgili kanıtları belirleyiniz.","hint":"Seçenekleri metnin bütünüyle karşılaştırınız.","keepOptionOrder":true,"plainText":true,"collection":"grade8-lgs-deneme-expanded"},{"grade":8,"topic":"Parçada anlam","difficulty":"Orta","outcome":"Paragrafta anlam, yapı ve anlatım özelliklerini belirler.","text":"Her hayvan türünün bir tür dili vardır. Örneğin yeşil maymunlar iletişim kurmak için çok çeşitli sesler çıkarır: “Dikkatli ol! Kartal geliyor! ya da “Dikkat et! Aslan” gibi. Araştırmacılar ilk kaydı dinlettiklerinde maymunlar korkuyla yukarıya bakmış. İkinci çağrıyı dinlettiklerinde ise maymunlar korkuyla ağaçlara tırmanmıştır. Biz insanlar ise oldukça farklıyız tabiî ki. Bir yeşil maymun, arkadaşına “Dikkat et! Aslan!” diye uyarı gönderebiliyorken, modern insan, arkadaşlarına sabah saatlerinde nehrin kıvrım yaptığı yerde bir bizon sürüsünü takip eden bir aslan gördüğünü söyleyebilir.","stem":"Bu parçada anlatılmak istenen asıl düşünce aşağıdakilerden hangisidir?","options":["İnsanların dili hayvanların dillerine oranla daha ayrıntılı ve karmaşık bir yapıdadır.","Canlılar kendilerini korumak için dili etkili bir şekilde kullanırlar.","Araştırmacılar deneyler yaparak maymunların dilleri hakkında bilgiler toplamışlardır.","Hayvanlar sadece birbirlerini anlayabilecek diller geliştirmişlerdir."],"answer":"A","solution":"Doğru cevap A seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Önce soru kökünü okuyup metindeki ilgili kanıtları belirleyiniz.","hint":"Seçenekleri metnin bütünüyle karşılaştırınız.","keepOptionOrder":true,"plainText":true,"collection":"grade8-lgs-deneme-expanded"},{"grade":8,"topic":"Dil ve anlatım","difficulty":"Orta","outcome":"Paragrafta anlam, yapı ve anlatım özelliklerini belirler.","text":"Türkiye’nin en renkli manzaralarından biri her perşembe Muğla’da kuruluyor. Isparta’nın kirazları, İzmir’in üzümleri, Manisa’nın kavunu, Dalaman’ın portakalı kurulan pazarda mevsimine göre sizi selamlar. Pazarcıların büyük çoğunluğu kadındır. Belki de bu yüzden pazar daha temiz ve düzenlidir. Her rengin boy ölçüştüğü bu yer yüzlerce meyve ve sebzeye geçici ev sahipliği yapar. Akşam olup güneş dünyaya küsünce geride sadece meyve ve sebzelerin artıkları ile birkaç kırık kasa kalır.","stem":"Bu metnin dil ve anlatımıyla ilgili aşağıdakilerden hangisi söylenemez?","options":["Kişileştirmeye başvurulmuştur.","Karşılaştırmadan yararlanılmıştır.","Deyim kullanılmıştır.","Anlatım birinci kişi ağzından yapılmaktadır."],"answer":"D","solution":"Doğru cevap D seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Önce soru kökünü okuyup metindeki ilgili kanıtları belirleyiniz.","hint":"Seçenekleri metnin bütünüyle karşılaştırınız.","keepOptionOrder":true,"plainText":true,"collection":"grade8-lgs-deneme-expanded"},{"grade":8,"topic":"Paragrafta sıralama","difficulty":"Orta","outcome":"Paragrafta anlam, yapı ve anlatım özelliklerini belirler.","text":"1) 1956’da ise gerekli yasalar çıkarılınca milli parklar kurulmaya başlandı. 2) 1800’lü yıllarda ABD’de ortaya atılan ve uygulamaya koyulan milli park projesi kısa sürede bütün dünyaya yayıldı. 3) Denizler için milli park kurmak ise ancak 1999’da gerçekleşebildi. 4) Hızla tahrip edilen doğayı insanlardan korumanın ve onlara geri vermenin yollarından biri, milli parklar kurmaktır. 5) Ülkemizde ise ilk önce art arda tabiatı koruma kanunları çıkarıldı.","stem":"Numaralanmış cümleler mantık akışına göre nasıl sıralanmalıdır?","options":["4- 1- 5- 3-","4- 2- 1- 3-","4 -2- 5- 1-","2- 4- 5- 1-"],"answer":"C","solution":"Doğru cevap C seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Önce soru kökünü okuyup metindeki ilgili kanıtları belirleyiniz.","hint":"Seçenekleri metnin bütünüyle karşılaştırınız.","keepOptionOrder":true,"plainText":true,"collection":"grade8-lgs-deneme-expanded"},{"grade":8,"topic":"Yardımcı düşünce","difficulty":"Orta","outcome":"Paragrafta anlam, yapı ve anlatım özelliklerini belirler.","text":"Dünya artık çok hızlı değişiyor. Önceden altın madenleri, buğday tarlaları ve petrol kuyuları gibi varlıklar temel zenginlik kaynağıyken, bugün en büyük zenginlik kaynağı bilgidir. Savaşla petrol kuyuları ele geçirebilirsiniz ama bilgiyi bu yolla elde edemezsiniz. Fakat eski usul ham madde ekonomileriyle yürüyen Ortadoğu ve Orta Afrika gibi belirli bölgelerde savaşlar sürmektedir. Bu parçada","stem":"aşağıdakilerden hangisine değinilmemiştir?","options":["Bilgiye ulaşmak için savaşılmaz.","Savaşlar dünyanın bazı yerlerinde karşımıza çıkmaktadır.","Ülkelerin en önemli zenginliği bilgiye sahip olmasıdır.","Büyük devletlerin oyunlarıyla ülkeler savaşa girmektedir."],"answer":"D","solution":"Doğru cevap D seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Önce soru kökünü okuyup metindeki ilgili kanıtları belirleyiniz.","hint":"Seçenekleri metnin bütünüyle karşılaştırınız.","keepOptionOrder":true,"plainText":true,"collection":"grade8-lgs-deneme-expanded"},{"grade":8,"topic":"Yardımcı düşünce","difficulty":"Orta","outcome":"Paragrafta anlam, yapı ve anlatım özelliklerini belirler.","text":"Şanlıurfa’ya öğretmen olarak atandığım ilk yıllarda bazı evlerin kapılarında “Reçel çekilir.” “Acı reçel bulunur.” yazıları dikkatimi çekerdi. Özellikle ara sokaklardaki eski evlerin pencerelerinde, kapılarında bu yazılara rastlardım. Reçel neden çekilirdi? Acı reçel nasıl olur? Çilek, kayısı, ayva reçellerinin memleketimde çekildiğini hiç görmemiştim. Meğer biber salçasının içine birkaç baharat koyup makinede çekince “reçel” oluyormuş. Bu","stem":"paragraftan aşağıdaki yargıların hangisine ulaşılamaz?","options":["İnsanlar alışık olmadığı nesnelere daha çok dikkat ederler.","Daha önce karşılaşılmayan durumlar insana farklı gelebilir.","İçinde bulunan çevre değiştikçe algılar da o çevreyle farklılaşır.","İnsanlar çevresini ihtiyaçlarına göre değiştirir."],"answer":"D","solution":"Doğru cevap D seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Önce soru kökünü okuyup metindeki ilgili kanıtları belirleyiniz.","hint":"Seçenekleri metnin bütünüyle karşılaştırınız.","keepOptionOrder":true,"plainText":true,"collection":"grade8-lgs-deneme-expanded"},{"grade":8,"topic":"Parçada anlam","difficulty":"Orta","outcome":"Paragrafta anlam, yapı ve anlatım özelliklerini belirler.","text":"(1) Zambakgiller ailesinden olan soğan hem sebze hem de baharat olarak mutfaklarda kullanılır. (2) Soğan, içerdiği kükürtlü birleşiklerden dolayı oldukça kötü bir koku yayar. (3) Eski Mısır’da piramitlerin yapımı sırasında işçilere bulaşıcı hastalıklardan korunmaları için soğan yedirilirdi. (4) Hem sebze hem et yemeklerinde lezzet vermek için kullanılan soğan salataların vazgeçilmez parçalarından biridir.","stem":"Numaralanmış cümlelerin hangisinde sebepsonuç ilişkisi vardır?","options":["1.","2.","3.","4."],"answer":"B","solution":"Doğru cevap B seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Önce soru kökünü okuyup metindeki ilgili kanıtları belirleyiniz.","hint":"Seçenekleri metnin bütünüyle karşılaştırınız.","keepOptionOrder":true,"plainText":true,"collection":"grade8-lgs-deneme-expanded"},{"grade":8,"topic":"Yardımcı düşünce","difficulty":"Orta","outcome":"Paragrafta anlam, yapı ve anlatım özelliklerini belirler.","text":"Türkçenin gücü ve söz varlığı konusundaki bilinen ilk bilinçli çalışma, Kâşgarlı Mahmut’un meşhur sözlüğü Divânü Lugâti’t-Türk’tür. Kâşgarlı Mahmut, 11. yüzyılda yaşamış büyük bir Türk bilgesidir. Kâşgarlı Mahmut, Türklük biliminin kurucusu ve büyük bir Türkologdur. Bu eserde Türk dili ilk defa bilinçli bir şekilde ele alınmıştır. Dîvânü Lugati’t-Türk, ilk bakışta bir sözlüğü andırmaktadır. Dîvânda 7.500’den fazla kelime açıklanıp örneklendirilmiştir. Eserde çok miktarda sav (atasözü), koşuk, şiir gibi halk edebiyatı malzemeleri yanında coğrafî, tarihî, mitolojik ve etnografik bilgiler de mevcuttur.","stem":"Bu parçada aşağıdaki sorulardan hangisinin cevabı yoktur?","options":["Kâşgarlı Mahmut kimdir?","Dîvânü Lugati’t-Türk’te hangi bilgiler bulunmaktadır?","Türkçe ilk defa hangi eserde sistemli bir şekilde işlenmiştir?","Dîvânü Lugati’t-Türk niçin hazırlanmıştır?"],"answer":"D","solution":"Doğru cevap D seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Önce soru kökünü okuyup metindeki ilgili kanıtları belirleyiniz.","hint":"Seçenekleri metnin bütünüyle karşılaştırınız.","keepOptionOrder":true,"plainText":true,"collection":"grade8-lgs-deneme-expanded"},{"grade":8,"topic":"Parçada anlam","difficulty":"Orta","outcome":"Paragrafta anlam, yapı ve anlatım özelliklerini belirler.","text":"(1) Finlandiya’nın eğitimde başarılı olmasında okulların öğrencilerin evi gibi düzenlenmesi ve eşit eğitim de yer alır. (2) Bu düzenleme içinde öğrenciler okula giderken üniforma giymezler. (3) Öğrenciler okula girişte elbiselerini askıya asar ve ayakkabılarını çıkarıp çoraplarıyla veya terlikleriyle derse girerler. (4) Araç, gereç ve teknolojinin yanı sıra sınıflarda öğrencilerin ellerini yıkamaları için lavabolar da bulunmaktadır.","stem":"Bu parçada numaralanmış cümlelerin hangisinde neden-sonuç ilişkisi vardır?","options":["1.","2.","3.","4."],"answer":"A","solution":"Doğru cevap A seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Önce soru kökünü okuyup metindeki ilgili kanıtları belirleyiniz.","hint":"Seçenekleri metnin bütünüyle karşılaştırınız.","keepOptionOrder":true,"plainText":true,"collection":"grade8-lgs-deneme-expanded"},{"grade":8,"topic":"Dil ve anlatım","difficulty":"Orta","outcome":"Paragrafta anlam, yapı ve anlatım özelliklerini belirler.","text":"Orhangazi ilçesinin Yeniköy’ünün tam ortasında kocaman bir çınar ağacı. Ağacın kolları altında sıra sıra dizilmiş kahvehaneler. Bazıları eski bazıları yeni sandalye ve masalarda saçları kırlaşmış köy sakinleri. Gençler ortada yok. Kaçıp gitmiş büyük çoğunluğu. Arkalarında yıkık dökük, geçmişi mumla arayan evler bırakarak.","stem":"Bu metnin dil ve anlatımıyla ilgili aşağıdakilerden hangisi söylenemez?","options":["Deyime yer verilmiştir.","İkileme kullanılmıştır.","Kişileştirmeye başvurulmuştur.","Benzetmeden yararlanılmıştır."],"answer":"D","solution":"Doğru cevap D seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Önce soru kökünü okuyup metindeki ilgili kanıtları belirleyiniz.","hint":"Seçenekleri metnin bütünüyle karşılaştırınız.","keepOptionOrder":true,"plainText":true,"collection":"grade8-lgs-deneme-expanded"},{"grade":8,"topic":"Çıkarım yapma","difficulty":"Orta","outcome":"Paragrafta anlam, yapı ve anlatım özelliklerini belirler.","text":"İskenderun’un en önemli özelliği Türkiye’nin mozaiği olmasıdır. Ülkemizin hemen her bölgesinden, her il ve ilçesinden göç alır. Bu nedenle içinde her çeşit çiçeğin yer aldığı bir bahçe gibidir İskenderun. Öyle bir bahçe ki, burada Anadolu’nun her yaylasının serin ve dinlendirici rüzgârı eser. Bu nedenledir ki bu bahçeden yükselen koku, insana ayrı bir haz ve huzur vermektedir. Diğer bir ifadeyle farklı örf ve adetlerin, gelenek ve göreneklerin birbiriyle tanışıp kaynaştığı, birleştiği, farklı kültürlerin el sıkışıp kucaklaştığı, güzel bir birliktelik sağladığı barış ve hoşgörü kentidir İskenderun.","stem":"Bu parçadan aşağıdakilerin hangisine ulaşılabilir?","options":["Çeşitli bahçelerin olması İskenderun’a ayrı bir güzellik katar.","İskenderun farklı kültürlere ev sahipliği yapmaktadır.","İskenderun sanayi bölgesi olduğu için sürekli göç almaktadır.","Farklı insanlar farklı kültürleri şehre getirince hoşgörü ortaya çıkmıştır."],"answer":"B","solution":"Doğru cevap B seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Önce soru kökünü okuyup metindeki ilgili kanıtları belirleyiniz.","hint":"Seçenekleri metnin bütünüyle karşılaştırınız.","keepOptionOrder":true,"plainText":true,"collection":"grade8-lgs-deneme-expanded"},{"grade":8,"topic":"Parçada anlam","difficulty":"Orta","outcome":"Paragrafta anlam, yapı ve anlatım özelliklerini belirler.","text":"Önümüzdeki yıllarda hiç kimse kitap almak için kitapçılara gitmeyecek. Kitapçılar bir bir kapanacak. İnsanlar bilgisayarın ve Genel Ağın büyülü dünyasında kitaplara bir tıkla ulaşacak. Sanal sayfaları çevirecek. Mürekkep ve sayfa kokusu, kitap ayraçları yok olacak. Sadece kitabı elimize almakla hissedilen bu ilişki de bitecek.","stem":"Bu parçada yazar niçin kaygılanmaktadır?","options":["Yeni kitapların yazılmayacağından","Kitapla kurulan ilişkinin sadece okumakla sağlanmasından","Bilgisayarların sadece kitap okumak amacıyla kullanılacağından","Teknolojinin kitapla kurulan ilişkiyi ortadan kaldıracağından"],"answer":"D","solution":"Doğru cevap D seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Önce soru kökünü okuyup metindeki ilgili kanıtları belirleyiniz.","hint":"Seçenekleri metnin bütünüyle karşılaştırınız.","keepOptionOrder":true,"plainText":true,"collection":"grade8-lgs-deneme-expanded"},{"grade":8,"topic":"Parçada anlam","difficulty":"Orta","outcome":"Paragrafta anlam, yapı ve anlatım özelliklerini belirler.","text":"(1) Nevâyî, Türkçeyi seyrine doyum olmayan bir gül bahçesine benzetir. (2)Türkçenin güneşten daha parlak güllerini toplayabilmek için çok çalışmak gerektiğini söyler. (3)Türkçenin devlet ve edebiyat dili olması hâlinde Türklerin de üstün bir millet olacağına inanır. (4) Ali Şîr Nevâyî’nin bir başka önemli yönü ise, Türk şiirine şekil ve ifade bakımından birtakım yenilikler getirmiş olmasıdır.","stem":"Bu parçada numaralanmış cümlelerden hangisinde koşul-sonuç ilişkisi vardır?","options":["1.","2.","3.","4."],"answer":"C","solution":"Doğru cevap C seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Önce soru kökünü okuyup metindeki ilgili kanıtları belirleyiniz.","hint":"Seçenekleri metnin bütünüyle karşılaştırınız.","keepOptionOrder":true,"plainText":true,"collection":"grade8-lgs-deneme-expanded"},{"grade":8,"topic":"Dil ve anlatım","difficulty":"Orta","outcome":"Paragrafta anlam, yapı ve anlatım özelliklerini belirler.","text":"Kıkırdak, yumuşak doku ve kemiklerden meydana gelmiş koklama ve nefes alma organıdır burun. Yüzün ön kısmında iki gözün arasında başlayıp piramit şeklinde uzanır ve ağzın üzerinde iki burun deliği ile son bulur. İnsan burnunda 1000 kadar koku reseptörü varken kedilerin burnunda 200 milyon kadardır. En iyi koku alan köpek ırkları bile kedilerle koku konusunda boy ölçüşemez.","stem":"Yukarıdaki metnin dil ve anlatımı için hangisi söylenemez?","options":["Kesin olan yargılar kullanılmıştır.","Bir kavram açıklanmıştır.","Samimi bir üslupla yazılmıştır.","Anlatımı güçlü kılmak için deyim kullanılmıştır."],"answer":"C","solution":"Doğru cevap C seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Önce soru kökünü okuyup metindeki ilgili kanıtları belirleyiniz.","hint":"Seçenekleri metnin bütünüyle karşılaştırınız.","keepOptionOrder":true,"plainText":true,"collection":"grade8-lgs-deneme-expanded"},{"grade":8,"topic":"Yardımcı düşünce","difficulty":"Orta","outcome":"Paragrafta anlam, yapı ve anlatım özelliklerini belirler.","text":"Konusu ve üslubunu çok iyi bildiğimiz bir kitabı bile tekrar okumalıyız. İyi yazılmış kitaplar tekrar tekrar okunduğu zaman nice hazineler sunar okuyucuya. Benzer biçimde, usta ressamların eserlerine de tekrar tekrar bakmalıyız. Onlara baktıkça yenilendiğimizi fark ederiz. Bu parçadan sanat yapıtlarıyla ilgili olarak","stem":"aşağıdakilerden hangisine ulaşılamaz?","options":["Sanat eserlerinin değeri yıllar geçince anlaşılır.","Bu eserler her seferinde bizde yeni duygular uyandırır.","Bir kez karşılaşmak bu eserler için yeterli olmaz.","Bazı güzelliklerin farkına varmak zaman alır."],"answer":"A","solution":"Doğru cevap A seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Önce soru kökünü okuyup metindeki ilgili kanıtları belirleyiniz.","hint":"Seçenekleri metnin bütünüyle karşılaştırınız.","keepOptionOrder":true,"plainText":true,"collection":"grade8-lgs-deneme-expanded"},{"grade":8,"topic":"Ana düşünce","difficulty":"Orta","outcome":"Paragrafta anlam, yapı ve anlatım özelliklerini belirler.","text":"Bir dilin zenginlik veya fakirliği söz konusu olduğunda, akla ilk olarak o dilin söz varlığı gelmektedir. Bu açıdan Türkiye Türkçesine bakıldığında, TDK’nin Türkçe Sözlüğünde bugün için 120.000’den fazla madde başı kelimenin var olduğu görülmektedir (Türkçe Sözlük, 2011). Bu sayı, Türkçenin tarihsel söz varlığını ifade etmekten çok uzaktır. Çünkü, günümüzde Anadolu’da halk ağzında kullanılan veya Türkçenin eski dönemlerine ait eserlerde kalmış ve bir kısmı artık kullanımdan düşmüş yüz binlerce kelime vardır. Bunun yanı sıra, bugün dünyanın çeşitli bölgelerinde Türkçe konuşan yaklaşık 250 milyon civarında bir Türk nüfusunun söz varlığı da dikkate alındığında kelime sayısının tahminî olarak 1 milyonun üzerine çıkabileceği söylenebilir.","stem":"Bu parçanın ana düşüncesi aşağıdakilerden hangisidir?","options":["Türkçe pek çok coğrafyada kullanılan bir dildir.","Türkçenin kelime sayısının sadece sözlüklere bakarak tespit edilmesi yanlıştır.","Kelimeler zamanla değerini kaybederler ve unutulurlar.","Dillerin zenginliğini kelime sayısına bakarak ölçmek gerekir."],"answer":"B","solution":"Doğru cevap B seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Önce soru kökünü okuyup metindeki ilgili kanıtları belirleyiniz.","hint":"Seçenekleri metnin bütünüyle karşılaştırınız.","keepOptionOrder":true,"plainText":true,"collection":"grade8-lgs-deneme-expanded"},{"grade":8,"topic":"Parçada anlam","difficulty":"Orta","outcome":"Paragrafta anlam, yapı ve anlatım özelliklerini belirler.","text":"Usta şair Yahya Kemal bir gün: Ben de yenilik taraftarıyım, ama yenilik tam olmalı: \" Eve geldim.\" yerine şöyle söylenmeli \" dim gel e ev\" Mehmet Âkif Ersoy Ziraat Fakültesine gitmek için tren istasyonunda beklerken gençlerin konuşmalarına kulak verir. Gençler: Bu sabah sen kaç trenini aldın? Sekiz trenini aldım, sen? Ben de dokuz trenini aldım. Dilimizi rahatsız eden \"tren almak\" sözlerine çok sinirlenen Akif, gençlere şöyle der: Çocuklar o treni daha hükümetiniz alamadı. Siz nasıl aldınız?","stem":"Bu metinlerdeki şairlerin ortak yönü aşağıdakilerden hangisidir?","options":["Şairlerin gençlere dil konusunda güvenmemeleri","Dildeki yeniliklerin Türkçenin kurallarına ve anlamlarına uygun olmasını istemeleri","Yenileşme hareketlerine şairlerin uyum sağlayamaması","Dilimize yerleşmeye çalışan yabancı sözcüklerin kullanılmamasını istemektedirler."],"answer":"B","solution":"Doğru cevap B seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Önce soru kökünü okuyup metindeki ilgili kanıtları belirleyiniz.","hint":"Seçenekleri metnin bütünüyle karşılaştırınız.","keepOptionOrder":true,"plainText":true,"collection":"grade8-lgs-deneme-expanded"},{"grade":8,"topic":"Metin türleri","difficulty":"Orta","outcome":"Paragrafta anlam, yapı ve anlatım özelliklerini belirler.","text":"Ahmet Hamdi Tanpınar’ın “Beş Şehir” isimli eseri yazarın diğer bütün eserlerinde anlatmaya çalıştığı tarih ve kültürün özetidir. Milli Eğitim müfettişliği döneminde gezdiği İstanbul, Bursa, Konya, Erzurum ve Ankara’yı kendine has üslubu ile betimler. Usta kalem, şehirleri anlatırken geçmiş ve gelecekle bağ kurmayı ihmal etmez. Bu bağ o kadar kuvvetli kurulur ki şehirler canlı ve dipdiri karşısına dikiliverir insanın.","stem":"Bu metin aşağıdaki yazı türlerinden hangisine örnek gösterilebilir?","options":["Günlük","Anı","Gezi yazısı","Eleştiri"],"answer":"D","solution":"Doğru cevap D seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Önce soru kökünü okuyup metindeki ilgili kanıtları belirleyiniz.","hint":"Seçenekleri metnin bütünüyle karşılaştırınız.","keepOptionOrder":true,"plainText":true,"collection":"grade8-lgs-deneme-expanded"},{"grade":8,"topic":"Ana düşünce","difficulty":"Orta","outcome":"Paragrafta anlam, yapı ve anlatım özelliklerini belirler.","text":"Nurullah Ataç, konuşur gibi, duyduğu gibi yazmaya çalıştı. Bu konuda şöyle der: “Yazı dilinin konuşma dilinden başka olmasını isteyen dar görüşlüler dilediklerince tepinsinler, devrik tümce giriyor, girdi yazı diline. Ben istediğim için değil, çağımız istediği için. Genci de ona gidiyor, yaşlısı da. Yaşsızlar vardır, yaşsız, çağsız, tatsız tuzsuz, ölü gibi yaşayanlar, bir onlar gitmiyor, gidemiyor konuşma diline. Konuşma dili, devrik tümce, yarının canlı, güzel ışıklı Türkçesi. Onun geldiğini göremeyenler, sezemeyenler kendilerine ağlasınlar!”","stem":"Bu parçada vurgulanan düşünce aşağıdakilerden hangisidir?","options":["Devrik cümle yazı dilimize girmemelidir.","Devrik cümle yapısı dilimize er ya da geç yerleşecektir.","Türkçedeki değişimlere herkes uyum sağlamalıdır.","Dil her zaman değişim içindedir ve kendini sürekli yeniler."],"answer":"B","solution":"Doğru cevap B seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Önce soru kökünü okuyup metindeki ilgili kanıtları belirleyiniz.","hint":"Seçenekleri metnin bütünüyle karşılaştırınız.","keepOptionOrder":true,"plainText":true,"collection":"grade8-lgs-deneme-expanded"},{"grade":8,"topic":"Yardımcı düşünce","difficulty":"Orta","outcome":"Paragrafta anlam, yapı ve anlatım özelliklerini belirler.","text":"Montaigne çevirileri yıllar yılı, zor olduğu kadar da tatlı bir uğraş oldu benim için. Çevirdikçe sevdim, sevdikçe çevirdim onu. Güzelim dilini hâlâ rahatça anlar duruma gelmiş değilim. Montaigne’in uydurduğu kelimeler bir yana, anlamları çok değişmiş ya da hiç kullanılmaz olmuş deyimler bir hayli şaşırtıp oyalıyor insanı. Ama öyle sıcak bir içtenliği var ki bu dilin seve seve uğraşıyorsunuz özüne varmaya. Çok yerde Montaıgne’i kendi çağında İngilizceye çeviren Floriot’ya başvurduğum oldu. Ama o da çok kez Montaigne’in kelimelerine kıyamayıp, olduğu gibi almış kendi diline.","stem":"Bu parçanın yazarı ile ilgili aşağıdaki yargılardan hangisine ulaşılamaz?","options":["Monteigne’nin eserlerini Türkçeye çevirmek yazar için güzel bir uğraştır.","Yazar çeviri yaparken başka kaynakları da kullanmak zorunda kalmıştır.","Zamanla değerini kaybeden kelimeler, uydurulan sözcükler yazarı zorlamıştır.","Bazı kelimelerin anlamlarını bulamayınca bu kelimelere dokunmamıştır."],"answer":"D","solution":"Doğru cevap D seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Önce soru kökünü okuyup metindeki ilgili kanıtları belirleyiniz.","hint":"Seçenekleri metnin bütünüyle karşılaştırınız.","keepOptionOrder":true,"plainText":true,"collection":"grade8-lgs-deneme-expanded"},{"grade":8,"topic":"Dil ve anlatım","difficulty":"Orta","outcome":"Paragrafta anlam, yapı ve anlatım özelliklerini belirler.","text":"Evcilleştirme, uygun bitki ve hayvanlardan çok daha fazla yiyecek elde edilmesine olanak sağlayan teknolojik ilerlemedir. İnsanların mısırın atası “teosint” adında yabani bir tahıl türünü toplamasıyla mısırın evcilleştirilmesi başlar. Teosint, koçanları oldukça küçüktür, boyu birkaç santimetredir. Şimdiki sapsarı mısırların yanında minicik kalır.","stem":"Bu parçanın anlatımıyla ilgili olarak aşağıdakilerden hangisi söylenemez?","options":["Tanımlamaya yer verilmiştir.","Karşılaştırma yapılmıştır.","Tanık göstermeye başvurulmuştur.","Pekiştirilmiş sözcük kullanılmıştır."],"answer":"C","solution":"Doğru cevap C seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Önce soru kökünü okuyup metindeki ilgili kanıtları belirleyiniz.","hint":"Seçenekleri metnin bütünüyle karşılaştırınız.","keepOptionOrder":true,"plainText":true,"collection":"grade8-lgs-deneme-expanded"},{"grade":8,"topic":"Parçada anlam","difficulty":"Orta","outcome":"Paragrafta anlam, yapı ve anlatım özelliklerini belirler.","text":"(1) Sebahat Hanım, annesiz kalan iki kediye kol kanat germişti. (2) Her gün şırınga içindeki sütle onları besliyor, sıcak tutmaya özen gösteriyordu. (3) Açlık, kedileri zayıf düşürür ve çabucak hasta eder. (4) Sadece onlar için içmediği halde süt alır ve sobayı yakardı.","stem":"Numaralanmış cümlelerden hangisi anlatımın akışını bozmaktadır?","options":["1.","2.","3.","4."],"answer":"C","solution":"Doğru cevap C seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Önce soru kökünü okuyup metindeki ilgili kanıtları belirleyiniz.","hint":"Seçenekleri metnin bütünüyle karşılaştırınız.","keepOptionOrder":true,"plainText":true,"collection":"grade8-lgs-deneme-expanded"},{"grade":8,"topic":"Paragraf tamamlama","difficulty":"Orta","outcome":"Paragrafta anlam, yapı ve anlatım özelliklerini belirler.","text":"Mehmet Akif’in Safahat eserinin ilk baskısında yer alan Arapça ve Farsça tamlamalar yerine daha sonraki baskılarda Türkçe ifadeler kullandığı görülmektedir. Örneğin; “Etfâli sefil” yerine “darmadağın yavrular” kelime grubunu kullanmıştır. Birçok…","stem":"Bu paragraf, konusu dikkate alındığında aşağıdakilerden hangisiyle tamamlanabilir?","options":["şair arkadaşının uyarısı yanlışlarını düzeltmesine sebep olmuştur.","yabancı kelime ve ibarenin Türkçeleşmiş olması onun şiirlerindeki sadelikle ilgilidir.","şair, şiirlerini eleştirdiği için şiirlerinin konusunu değiştirmiştir.","kişi onu yabancı kelimeleri kullandığı için yadırgamıştır."],"answer":"B","solution":"Doğru cevap B seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Önce soru kökünü okuyup metindeki ilgili kanıtları belirleyiniz.","hint":"Seçenekleri metnin bütünüyle karşılaştırınız.","keepOptionOrder":true,"plainText":true,"collection":"grade8-lgs-deneme-expanded"},{"grade":8,"topic":"Parçada anlam","difficulty":"Orta","outcome":"Paragrafta anlam, yapı ve anlatım özelliklerini belirler.","text":"(I) Sığla ağacı, endemik bir ağaç türü olup 300 yıl kadar uzun ömre sahiptir ve boyu, 15-20 metre olup uygun koşullarda 35-40 metreye ulaşır. (II) Sığla ağacının baharda filizlenen taze, küçük yaprakları haşlandıktan sonra kavurmak suretiyle yemek yapılır. (III) Sığla, dünyada doğal olarak belli yerlerde yetişir. (IV)Türkiye’de en geniş yayılışını Muğla’da özellikle de Marmaris, Dalaman, Köyceğiz ve Fethiye dolaylarında gösterir.","stem":"Bu parçada numaralanmış cümlelerden hangisi parçanın anlam bütünlüğünü bozmaktadır?","options":["I.","II.","III.","IV."],"answer":"B","solution":"Doğru cevap B seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Önce soru kökünü okuyup metindeki ilgili kanıtları belirleyiniz.","hint":"Seçenekleri metnin bütünüyle karşılaştırınız.","keepOptionOrder":true,"plainText":true,"collection":"grade8-lgs-deneme-expanded"},{"grade":8,"topic":"Yardımcı düşünce","difficulty":"Orta","outcome":"Paragrafta anlam, yapı ve anlatım özelliklerini belirler.","text":"İki buçuk yıldır on yaş üstü okurlarım için arama kurtarma köpekleriyle ilgili 3 kitaplık, her sayfası renkli fotoğraflı basılacak bir dizi üstünde araştırmalar yapıyorum. Hazırladığım dizinin adı: Arama Kurtarma Köpekleri. Diziyi hazırlarken, birçok köpek eğitim okulunda araştırmalar yaptım. Steril tulum, ayakkabı, şapka giyerek Alman kurdu bir arama kurtarma köpeğin doğumunu izledim. Kitaplarımda o anneden doğan 4 köpek yavrusunun eğitim süreçlerinden başlayarak, görev sırasında yaşadıkları akıl almaz maceraları kaleme aldım. Özel olarak eğitilen köpek kahramanlarımla sevgili okurlarım ulusal ve evrensel nitelikte bin bir çeşit serüvene atılacaklar. Gerçekten, pek özel ve özgün konu ve değişik kurgularla örüldü bu öyküler.","stem":"Bu parçada aşağıdaki sorulardan hangisinin cevabı yoktur?","options":["On yaş üstü okurlara hitap etmenizin sebebi nedir?","Kitaplarınızı hazırlarken neler yaptınız?","Kitaplarınızın fiziksel özellikleri nelerdir?","Öykülerinizin konusu nedir?"],"answer":"A","solution":"Doğru cevap A seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Önce soru kökünü okuyup metindeki ilgili kanıtları belirleyiniz.","hint":"Seçenekleri metnin bütünüyle karşılaştırınız.","keepOptionOrder":true,"plainText":true,"collection":"grade8-lgs-deneme-expanded"},{"grade":8,"topic":"Çıkarım yapma","difficulty":"Orta","outcome":"Paragrafta anlam, yapı ve anlatım özelliklerini belirler.","text":"Montaigne amma da fikir çalmış benden! Beranger Denemeler’de gördüğüm her şeyi Montaigne’de değil kendimde buluyorum. Pascal Bir kitap buldum burada, Montaigne’in kitabı; yanıma almadım sanıyordum. Aman ne hoş adam. Ne zevk onunla beraber olmak. Mme. de Sevigne","stem":"Yukarıdaki cümlelerden hareketle Montaigne’nin “Denemeler” eseriyle ilgili aşağıdakilerden hangisine ulaşılabilir?","options":["Eser bu kişilerin katkılarıyla oluşturulmuştur.","Denemeler, bu kişilerin duygu ve düşüncelerine hitap etmektedir.","Montaigne, bu kişilerin görüşlerine saygı duymuştur.","Eser hakkında eleştiri yapmak eserin tanınması için önemlidir."],"answer":"B","solution":"Doğru cevap B seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Önce soru kökünü okuyup metindeki ilgili kanıtları belirleyiniz.","hint":"Seçenekleri metnin bütünüyle karşılaştırınız.","keepOptionOrder":true,"plainText":true,"collection":"grade8-lgs-deneme-expanded"},{"grade":8,"topic":"Parçada anlam","difficulty":"Orta","outcome":"Paragrafta anlam, yapı ve anlatım özelliklerini belirler.","text":"Çocuk hikâye ve romanlarında karakterler iyi belirlenmiş olmalıdır. Küçük çocuklar, önceleri kalıp hâlindeki güzellik ve iyilik simgelerini ararken, bir süre sonra kendileri gibi canlı ve doğal kahramanlar isterler. İyi çizilmiş karakterler yoluyla kendi sorunlarını çözebilir, çevrelerine yeni bir anlayış ve görüşle bakabilirler.","stem":"Bu parçaya göre çocuklar için yazılan hikâye ve romanlardaki karakterlerin taşıması gereken nitelik aşağıdakilerden hangisidir?","options":["Farklı kişilerin yansımaları olmalıdır.","Sürekli bir değişim içinde çocukları şaşırtmalıdır.","Karakterler çocukların dünyalarını yansıtabilmelidir.","Renkli ve resimli olmaları karakterleri akılda daha kalıcı bir hâle getirir."],"answer":"C","solution":"Doğru cevap C seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Önce soru kökünü okuyup metindeki ilgili kanıtları belirleyiniz.","hint":"Seçenekleri metnin bütünüyle karşılaştırınız.","keepOptionOrder":true,"plainText":true,"collection":"grade8-lgs-deneme-expanded"},{"grade":8,"topic":"Ana düşünce","difficulty":"Orta","outcome":"Paragrafta anlam, yapı ve anlatım özelliklerini belirler.","text":"Numantia, İspanya’nın önemsiz ve sıradan bir kasabasıdır. M.Ö 134’te Roma’ya köle olmamak için baş kaldırır ve özgürlük uğruna kendi şehirlerini yakıp yıkar, kendi canlarına kıyarlar. İspanyollar bu mücadele ruhunu canlı tutabilmek için hayali bir kahraman olan El Jabato’nun maceralarını gençlerine rol model olarak sunarlar. Peki biz neden rol model sunmuyoruz? Her yanımız Süpermen, Batman, Örümcek Adam gibi hayali kahramanlar sarmışken neden gençlerimize kanlı canlı gerçek kahramanlarımızı rol model aldırmıyoruz? Osman Paşa’nın Plevne kahramanlığını, Seyit Onbaşı’nın fedakârlığını ya da bir emirle kendi canını bile feda edebilecek kadar itaatkâr askerlerimizi neden gençlerimize tanıtmıyoruz? Çantalarda, kalemliklerde, suluklarda, defterlerde onların fotoğrafları olsa daha iyi olmaz mı?","stem":"Bu parçada asıl anlatılmak istenen aşağıdakilerden hangisidir?","options":["Bütün milletler kendilerine kahraman yaratmışlardır.","Tarihimiz birçok kahramanı bünyesinde barındırmaktadır.","Gençlerimize, gerçek kahramanlarımızı örnek olarak gösterecek adımlar atmalıyız.","İspanyollar tarihlerine sahip çıkarken hayali kahramanları benimsemezler."],"answer":"C","solution":"Doğru cevap C seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Önce soru kökünü okuyup metindeki ilgili kanıtları belirleyiniz.","hint":"Seçenekleri metnin bütünüyle karşılaştırınız.","keepOptionOrder":true,"plainText":true,"collection":"grade8-lgs-deneme-expanded"},{"grade":8,"topic":"Metin türleri","difficulty":"Orta","outcome":"Paragrafta anlam, yapı ve anlatım özelliklerini belirler.","text":"Bir insanı, hayatının belli başlı hâllerine bakarak yargılamak bize doğru gibi gelir; ama inanç ve âdetlerimizin mayasındaki kararsızlığı gördükçe, bana öyle geliyor ki, büyük yazarlar bile bizi her yerde, her zaman hep aynı kalan bir varlık olarak görmekle yanılmışlardır. İnsanın, herkesçe bilinen bir yüzünü alıyorlar, sonra bütün hareketlerini bu yüze uydurup anlatıyorlar; uyduramadıklarının birçoğunu hasıraltı ediyorlar.","stem":"Bu parça aşağıdaki metin türlerinin hangisinden alınmıştır?","options":["Deneme","Makale","Destan","Eleştiri"],"answer":"A","solution":"Doğru cevap A seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Önce soru kökünü okuyup metindeki ilgili kanıtları belirleyiniz.","hint":"Seçenekleri metnin bütünüyle karşılaştırınız.","keepOptionOrder":true,"plainText":true,"collection":"grade8-lgs-deneme-expanded"},{"grade":8,"topic":"Parçada anlam","difficulty":"Orta","outcome":"Paragrafta anlam, yapı ve anlatım özelliklerini belirler.","text":"Richard Feynman, bilimi herkese yayma çabaları ve verdiği seminerlerle fizikçiler arasında tanınmış bir bilim adamıdır. 1959'da bir konferansta bir konuşma yapmış ve konuşmasında, eğer atom ve molekül büyüklüklerinde imalat yapılabilirse birçok yeni keşif olabileceğini söylemiştir. Ayrıca böyle bir şeyin gerçekleşebilmesi için ilk başta nano ölçekte özel ölçme ve üretim yöntemlerinin geliştirilmesi gerektiğini belirtmiştir. Feynman'ın bu konuşması, nanobilim ve nano-teknolojinin başlangıcı kabul edilmektedir. Bu konuşmadan günümüze kadar taramalı, tünellemeli mikroskop, karbon nanotoplar ve karbon nanotüpler gibi önemli teknolojik gelişmeler sağlandı. Yakın gelecekte tıp ve sağlık alanında üretilebilecek yeni ürünleri heyecanla bekliyoruz. Bu parça için kullanılabilecek en uygun başlık","stem":"aşağıdakilerden hangisidir?","options":["Tıp ve Sağlık Alanındaki Gelişmeler","Teknoloji ve Nanoteknoloji Farkı","Nanoteknolojinin Doğuşu ve Gelişimi","Nanoteknolojinin Gelişmesindeki Engeller"],"answer":"C","solution":"Doğru cevap C seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Önce soru kökünü okuyup metindeki ilgili kanıtları belirleyiniz.","hint":"Seçenekleri metnin bütünüyle karşılaştırınız.","keepOptionOrder":true,"plainText":true,"collection":"grade8-lgs-deneme-expanded"},{"grade":8,"topic":"Parçada anlam","difficulty":"Orta","outcome":"Paragrafta anlam, yapı ve anlatım özelliklerini belirler.","text":"Bazı insanların gelecek, düşünceleri aşırı bir ümit ve sonsuz bir güven içindedir. Böyle olmasına rağmen bunun için bir şey yapmamaları da düşündürücü. İlmi ve bedeni bir faaliyet, plan ve projenin olmadığı sonsuz güven ve gelecek ümidi düşünülebilir mi? Sadece hayal, hedefe bir nebze olsun yaklaşamayacak boş bir hayalperestlik. Peki, geleceği tasarlamak için hayal kurulmaz mı? Elbette kurulur ancak bunun adı \"hayal\" değil \"ümit\"tir. Ümit ile hayal arasındaki ince çizgi ise çalışmadır. Çalışılır ve sonuç ümitle beklenir. Hiçbir şey yapmadan sırf ümit, ümit değil hayaldir.","stem":"Bu parçada yazarın asıl yakındığı durum aşağıdakilerden hangisidir?","options":["Ümit ve hayal kavramlarının insanlar tarafından bilinmemesi","Kimi insanların hiç çaba sarf etmediği halde gelecek hakkında gereksiz güvene sahip olması","Yapılan plan ve projelerin gerçeğe uygun olmaması","İnsanların hedeflerine ulaşma yolundan hemen vazgeçmeleri"],"answer":"B","solution":"Doğru cevap B seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Önce soru kökünü okuyup metindeki ilgili kanıtları belirleyiniz.","hint":"Seçenekleri metnin bütünüyle karşılaştırınız.","keepOptionOrder":true,"plainText":true,"collection":"grade8-lgs-deneme-expanded"},{"grade":8,"topic":"Yardımcı düşünce","difficulty":"Orta","outcome":"Paragrafta anlam, yapı ve anlatım özelliklerini belirler.","text":"İnternetin gelmesine, hayatımızda yer etmesine alışmıştım da internetle beraber sosyal medyanın da günlük hayatımızın yapılması gereken işler listesinde olmasına alışamadım bir türlü. Öyle ki sabah uyanır uyanmaz telefonu elimize alıp bildirimlere bakmayı görev atfettik adeta. Paylaştığımız resimlerin kaç beğeni aldığı, o resimlere kaç yorum yapıldığını sayar olduk. Yorum ve beğeni sayısı sevildiğimizin ölçütü oldu neredeyse. Yediğimiz her şeyi, gezdiğimiz her yeri herkese duyurarak mahremiyet kavramını bitirdik. Artık evlerimizde değil, ellerimizdeki akıllı kutularda yaşar olduk hayatı.","stem":"Bu parçadan aşağıdaki yargılardan hangisine ulaşılamaz?","options":["Sosyal medyanın günlük işlerimizden biri olduğuna.","Hayatımızı herkesin önünde yaşadığımıza.","Paylaşımı çok beğenilen insanın çok sevildiğini zannettiğine.","İnsanların evlerinde bile birbiriyle iletişim kurmadığına."],"answer":"D","solution":"Doğru cevap D seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Önce soru kökünü okuyup metindeki ilgili kanıtları belirleyiniz.","hint":"Seçenekleri metnin bütünüyle karşılaştırınız.","keepOptionOrder":true,"plainText":true,"collection":"grade8-lgs-deneme-expanded"},{"grade":8,"topic":"Ana düşünce","difficulty":"Orta","outcome":"Paragrafta anlam, yapı ve anlatım özelliklerini belirler.","text":"Söyleyiş güzelliğini yansıtan manilerimiz bölgeden bölgeye, yöreden yöreye fark edebilir mi? Bence fark eder. Çünkü bölgelerimiz ve yörelerimiz coğrafi olarak birbirinden ayrılır. Karadeniz manilerinde hamsiler yüzerken, Ege manilerinde zeybekler oynar, Güneydoğu manilerimizin biberi ise ağzımızı yakar.","stem":"Bu parçada asıl anlatılmak istenen aşağıdakilerden hangisidir?","options":["Geleneklere bağlı hayat sürmek manilerimizi geliştirir.","Manilerimiz çevrenin etkisiyle ortaya çıkar ve farklı özellik gösterir.","Sanat anlayışımızın gelişmesi için etkileşim şarttır.","Manilerdeki söyleyiş güzelliğinin farkına varmalıyız."],"answer":"B","solution":"Doğru cevap B seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Önce soru kökünü okuyup metindeki ilgili kanıtları belirleyiniz.","hint":"Seçenekleri metnin bütünüyle karşılaştırınız.","keepOptionOrder":true,"plainText":true,"collection":"grade8-lgs-deneme-expanded"},{"grade":8,"topic":"Parçada anlam","difficulty":"Orta","outcome":"Paragrafta anlam, yapı ve anlatım özelliklerini belirler.","text":"","stem":"Aşağıdaki metinlerden hangisi yay ayraç içinde verilen türde yazılmamıştır?","options":["Kurnaz tilki; dağları aşmış, ormanları dolaşmış, tavşanı kovalamış, tazıyı oyalamış, epeyce yorulmuş. Erkenden uyumuş. Derin uykulara dalmış. Gecenin ilerleyen saatlerinde bir de bakmış ki kuyruğu yok. Hemen kuyruğunu aramaya çıkmış. Kürkünün içine bakmış ama bulamamış. (fabl)","O gün ödevlerim erken bitmişti. Hemen sokağa çıkmıştım. Mahalledeki arkadaşlarım da yanıma geldiler. Oynamaya başladık. Her oyunu birkaç kez oynuyorduk. İyice oynayıp yorulmuştum. Eve gidince geç kaldığım için annemden azar işitmiştim. (anı)","Adım Anton ÇEHOV. 1860 yılında Azak Denizi kıyısındaki Taganrog’da doğdum. İlk ve ortaokulu doğduğum kentte tamamladım. 1879’da tıp öğrenimi görmek için Moskova’ya gittim. Öğrenim yıllarımda aileme maddi destek olmak için gazete ve dergilerde takma adla kısa mizah öyküleri yazdım. (biyografi)","İnsanlar her zaman sorunlarından arınmaya çalışırlar ve bunu yaparken de farklı yöntemler izlerler. Yazmak da bunlardan biridir. Ne yazık ki yazarak aramıza koyduğumuz sorunlardan kurtulamıyoruz. Ama yine de yazmaya devam ediyoruz. (deneme)"],"answer":"C","solution":"Doğru cevap C seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Önce soru kökünü okuyup metindeki ilgili kanıtları belirleyiniz.","hint":"Seçenekleri metnin bütünüyle karşılaştırınız.","keepOptionOrder":true,"plainText":true,"collection":"grade8-lgs-deneme-expanded"},{"grade":8,"topic":"Konu bulma","difficulty":"Orta","outcome":"Paragrafta anlam, yapı ve anlatım özelliklerini belirler.","text":"İnsanların tüketim arzuları dizginlenemez bir seviyeye ulaştı. Tüketim çağı denilen bu süreç, ne sadece ceplere ne sadece midelere hücum ediyor. Tüketim çılgınlığı çok farklı ve zararlı maskeler altında çok geniş bir sahada yayıldı ve hızla yayılmaya devam ediyor. Mesela kitapları ele alalım. Çok satan kitap listeleri hızla değişiyor. Kitapların biri okunup sindirilmeden ve toplum genelinde istenilen tesiri göstermeden raflardaki yerini yenilerine bırakıyor. Bu hızlı değişim verimden yoksun hikâyeler mezarlığı olmuş zihinlerde. Bir üst rafa çıkma kaygısıyla hızla hazırlanan hormonlu fikirler bir yandan yeni nesli zehirliyor diğer yandan da eskiler bu duruma yavaşça şahitlik ediyor.","stem":"Bu metnin konusu aşağıdakilerden hangisidir?","options":["Hızlı değişime insanların ayak uydurması gerekliliği","Tüketim çağındaki insanların kaygıları","Çok satan ürünlerin özellikleri","Tüketim fazlalığının yol açtığı olumsuzluklar"],"answer":"D","solution":"Doğru cevap D seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Önce soru kökünü okuyup metindeki ilgili kanıtları belirleyiniz.","hint":"Seçenekleri metnin bütünüyle karşılaştırınız.","keepOptionOrder":true,"plainText":true,"collection":"grade8-lgs-deneme-expanded"},{"grade":8,"topic":"Yardımcı düşünce","difficulty":"Orta","outcome":"Paragrafta anlam, yapı ve anlatım özelliklerini belirler.","text":"Orta ve Güney Amerika’daki Yağmur Ormanları’nda yaşayan miskin hayvan; dünyanın en tembel, en yavaş hareket eden hayvanı olarak da biliniyor. Yapılan araştırmalarda hız yeteneğinden yoksun bu sevimli hayvanların dakikada en fazla yarım metre ilerleyebildikleri gözlemlenmiştir. Genellikle ağaçlarda yaşayan, ayakları kancalı bu hayvanların boyu 50-60 cm arasındadır. Ömürleri 12 ila 15 yıl arasında değişen bu tembel hayvanlar otoburdurlar.","stem":"Bu parçada aşağıdakilerden hangisine değinilmemiştir?","options":["Beslenme şekillerine","Yaşadıkları coğrafyaya","Günlük hareketlerine","Fiziksel görüntülerine"],"answer":"C","solution":"Doğru cevap C seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Önce soru kökünü okuyup metindeki ilgili kanıtları belirleyiniz.","hint":"Seçenekleri metnin bütünüyle karşılaştırınız.","keepOptionOrder":true,"plainText":true,"collection":"grade8-lgs-deneme-expanded"},{"grade":8,"topic":"Parçada anlam","difficulty":"Orta","outcome":"Paragrafta anlam, yapı ve anlatım özelliklerini belirler.","text":"(1) İçinde yaşadığım toplumun gerçeklerinin farkına varmak için mutlaka kitap, gazete, dergi okurum.(2) Bir toplumun insanları ve yaşam gerçekleri hakkında bilgi almak istiyorsak o toplumda yayımlanan güncel yazın kaynaklarını takip etmek en doğrusu.(3) Bu eserler doğdukları toplumu her yönüyle yansıtır.(4) Bu nedenle okuduğum her kitapta, dergide, gazetede bir sürü toplumsal gerçekle tanışırım.","stem":"Bu parçada numaralandırılmış cümlelerden hangisinde amaç-sonuç ilişkisi vardır?","options":["1.","2.","3.","4."],"answer":"A","solution":"Doğru cevap A seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Önce soru kökünü okuyup metindeki ilgili kanıtları belirleyiniz.","hint":"Seçenekleri metnin bütünüyle karşılaştırınız.","keepOptionOrder":true,"plainText":true,"collection":"grade8-lgs-deneme-expanded"},{"grade":8,"topic":"Parçada anlam","difficulty":"Orta","outcome":"Paragrafta anlam, yapı ve anlatım özelliklerini belirler.","text":"Havuza ya da denize girip uzun süre suya maruz kaldığımız zaman vücudumuzun bazı yerleri kırış kırış olur. Avuç içlerimiz, ayak tabanlarımız kırışırken, diğer bölgelerimiz böyle bir tepki vermez. Vücudumuzun birçok yerinde gözle göremeyeceğimiz kadar küçük tüylerden –mikroskopla bunları görebilirsinizoluşan bir ordu bulunur. Bu tüylerin arasında da birçok yağ bezi bulunur. Bu yağ bezleri derimizin üzerinde su geçirmez bir tabaka oluşturur. Elimizin içinde ve ayak tabanlarında tüyler olmadığı için su geçirmez özelliği yoktur. Bu sebeple su bu bölgelerden yavaş yavaş vücudumuza girer. Üstteki deri tabakası suyu emdiği için genişlemeye başlar, genişledikçe yer bulamayan su derimizi kırıştırır. Bu durum vücudumuza herhangi bir zarar vermez. Çünkü bir süre sonra sular oradan gider ve deri eski haline döner. Eğer vücudumuzun diğer bölgelerinde tüyler olmasaydı her yerimiz kırış kırış olur acayip bir şeye benzerdik. Bu parça için kullanılabilecek en uygun başlık","stem":"aşağıdakilerden hangisidir?","options":["Suda fazla kalınca neden el içlerimiz ve ayak tabanlarımız buruşur?","Vücudumuzun her yerinde tüy olmamasının sebebi nedir?","Suda fazla kalınca neler yapmalıyız?","Yağ bezlerinin çalışma koşulları nasıldır?"],"answer":"A","solution":"Doğru cevap A seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Önce soru kökünü okuyup metindeki ilgili kanıtları belirleyiniz.","hint":"Seçenekleri metnin bütünüyle karşılaştırınız.","keepOptionOrder":true,"plainText":true,"collection":"grade8-lgs-deneme-expanded"},{"grade":8,"topic":"Yardımcı düşünce","difficulty":"Orta","outcome":"Paragrafta anlam, yapı ve anlatım özelliklerini belirler.","text":"Dünya turuna çıkmak bir zamanlar olduğu gibi çok nadir bir şey değil. Günümüzde maceraya atılarak çeşitli araçlarla hatta yürüyerek bile dünya turuna çıkan maceraperest gezginler var. Kendisine Tony The Traveller adını veren Tony Giles da onlardan biri. Yıllardır dünya turunda olduğunu ve en son geçen ay Kudüs'e uğrayarak seyahatinde 124'üncü ülkeye ayak bastığını ileri süren Tony Giles'in bu kadar yer gezdikten sonra çok şey görmüş olduğunu düşünebilirsiniz ancak o aslında gezdiği 124 ülkede şu ana kadar hiçbir şey görmedi ve bir mucize olmazsa göremeyecek de çünkü Tony'nin iki gözü de görmüyor. İşin daha tuhafı, bu dünya gezgininin iki kulağında da %80 oranında işitme kaybı var. Bugüne kadar Arktik Dairesi dâhil altı kıtaya da ayak bastığını ileri süren Tony Giles, sık sık yolunu kaybetmesine rağmen yalnız seyahat etmek gibi bir zorluğu göze almasının en büyük nedenini: \"Her işi kendim yaparak hayata meydan okumak ve mümkün olduğunca çok insanla temas kurmak\" olarak açıklıyor.","stem":"Bu parçada anlatılan kişiyle ilgili aşağıdakilerden hangisi söylenemez?","options":["Fiziksel yetersizliklerine rağmen hedeflerinin peşinden gitmektedir.","Seyahatlerini gerçekleştirirken çeşitli zorluklar yaşamaktadır.","Hiçbir şey görmemesine ve büyük oranda duymamasına rağmen yalnız seyahat etmektedir.","Yıllardır yüz yirmi dört ülke görmüş ve evine uğramamıştır."],"answer":"D","solution":"Doğru cevap D seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Önce soru kökünü okuyup metindeki ilgili kanıtları belirleyiniz.","hint":"Seçenekleri metnin bütünüyle karşılaştırınız.","keepOptionOrder":true,"plainText":true,"collection":"grade8-lgs-deneme-expanded"},{"grade":8,"topic":"Parçada anlam","difficulty":"Orta","outcome":"Paragrafta anlam, yapı ve anlatım özelliklerini belirler.","text":"Potansiyel kayıp fikri insanların karar vermesinde büyük bir rol oynamaktadır. Birçok insan bir şeyi kazanmak düşüncesinden daha çok, onu kaybetme endişesiyle ikna olurlar. Koleksiyoncular ve antikacılar bir eserin değerini belirlemede nadirlik etkisini en iyi bilen insanlardır. Çünkü bir ürünün azalması onun satılması ihtimalini arttırmaktadır. Normal koşullarda satın alınması ertelenecek hatta belki hiç alınmayacak bir ürün eğer son bir iki adet kalmışsa ya da bir daha bulunması söz konusu değilse o ürüne talep de doğal olarak artacaktır. Caldini, yaptığı bir deneyinde; kavanozda on tane varken yenilen kurabiyenin lezzeti ile kavanozda iki tane varken yenilen kurabiyenin lezzetinin farklı olduğunu söyler. Az kalan bir ürünün lezzeti artmaktadır. Bu parçada asıl anlatılmak istenen düşünce","stem":"aşağıdakilerden hangisidir?","options":["Bir ürün ne kadar pahalıya satılırsa o kadar kıymetlidir.","Bir ürünü almadan önce işe yararlılığına bakmalıyız.","Bir ürüne asıl değeri antikacılar ve koleksiyoncular verir.","Bir ürünün kıymetinin artmasında az ve nadir bulunması etkilidir."],"answer":"D","solution":"Doğru cevap D seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Önce soru kökünü okuyup metindeki ilgili kanıtları belirleyiniz.","hint":"Seçenekleri metnin bütünüyle karşılaştırınız.","keepOptionOrder":true,"plainText":true,"collection":"grade8-lgs-deneme-expanded"},{"grade":8,"topic":"Yardımcı düşünce","difficulty":"Orta","outcome":"Paragrafta anlam, yapı ve anlatım özelliklerini belirler.","text":"Bir alaylı olarak, önce muhabir olarak başladım gazeteciliğe. O zamanlar usta çırak ilişkisi ile öğrenilirdi gazetecilik. Öyle oturduğun yerden dikkat çekici bir başlık atarak okuyucu kandırmak değildi bizim ağabeylerimizden öğrendiğimiz. Haberi araştırarak, sorgulayarak ve tarafsızca sunmak gerekiyordu okuyucuya. Şimdi 50. yılımı kutlarken mesleğe veda edişimin sebebi de budur aslında. Günümüzde elinde telefonu, tableti, bilgisayarı olan herkes birer gazeteci(!) ve her bilgi herkese anında ulaşıyor. Daha da kötüsü kimse haberin doğruluğunu önemsemiyor. Bir de bakıyorsunuz ortada yalan yanlış bilgiler, haberler…","stem":"Bu parçada aşağıdaki sorulardan hangisinin cevabı yoktur?","options":["Emekli olmanızın sebebi nedir?","Gazetecilik için hangi eğitimi aldınız?","Günümüzdeki gazetecileri nasıl değerlendiriyorsunuz?","Bu mesleğe hangi yıl başladınız?"],"answer":"C","solution":"Doğru cevap C seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Önce soru kökünü okuyup metindeki ilgili kanıtları belirleyiniz.","hint":"Seçenekleri metnin bütünüyle karşılaştırınız.","keepOptionOrder":true,"plainText":true,"collection":"grade8-lgs-deneme-expanded"},{"grade":8,"topic":"Metin türleri","difficulty":"Orta","outcome":"Paragrafta anlam, yapı ve anlatım özelliklerini belirler.","text":"","stem":"Aşağıdaki metinlerden hangisi bir hikâyeden alınmıştır?","options":["Akşam olmak üzereydi. Abdullah her günkü gibi bisikletine binip okuldan eve dönüyordu. Eve yaklaşmıştı ama eve varmadan yolda bir köpekle karşılaşmıştı. Bu yüzden yolunu değiştirmek zorunda kaldı.","Topkapı Sarayı’nı gezdikten sonra karşı yakada bulunan Çamlıca Tepesi’ne de çıkmak istedik. Karşıya geçince yola yürüyerek çıkmayı tercih ettik. On dakikalık bir yürüyüşten sonra tepeye çıktık ve muhteşem bir manzarayla karşılaştık.","Yükseldikçe boynunu bükmeli insan, başak misali. Tavır ve hareketlerine azami özen göstermeli. Bir zamanlar her şeyini paylaştığın arkadaşların, senin yükseldiğini gördüklerinde:’’Makam mevki onu değiştirmemiş, hatta daha da alçak gönüllü olmuş.’’diyebilmeli.","Bir zamanlar geyiğin biri ormanda geziniyormuş. Çok susamış, derenin başına gitmiş. Suya başını daldırınca bir de ne görsün? Boynuzları çok gösterişli, bacakları ise incecik bir geyikmiş."],"answer":"A","solution":"Doğru cevap A seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Önce soru kökünü okuyup metindeki ilgili kanıtları belirleyiniz.","hint":"Seçenekleri metnin bütünüyle karşılaştırınız.","keepOptionOrder":true,"plainText":true,"collection":"grade8-lgs-deneme-expanded"},{"grade":8,"topic":"Yardımcı düşünce","difficulty":"Orta","outcome":"Paragrafta anlam, yapı ve anlatım özelliklerini belirler.","text":"Gezdiği gördüğü topraklarda, oraların değerlerine dair anlattığı şeyler, verdiği bilgiler neredeyse bir tarihe ışık tuttu. Tabii onu farklı kılan özelliklerden biri de metinlerde başvurduğu mübalağalı ifadeler ve yer yer fantastik unsurları içeren olaylar. Çok bilinen bir örnek: Erzurum'da kışın bir kedinin damdan dama atlarken havada donup yere düşmesi… Elbette burada Erzurum'un ne kadar soğuk olduğunu anlatmak için böyle bir anlatıma başvurdu Evliya Çelebi fakat bunu öyle ustalıkla yapıyordu ki okuyanlar yüzyıllar sonra bile gerçek ile fantastiği, kurgu ile hakikati tam olarak ayıramıyordu birbirinden.","stem":"Bu parçadan yazarla ilgili aşağıdakilerden hangisi çıkarılamaz?","options":["Yazar anlatımında gerçeklere tamamen bağlıdır.","Anlatımında sanatlı söyleyişlere yer verebilmektedir.","Belge niteliğinde bilgi olarak kullanılabilir yazarın anlattıkları.","Eserleri zamana direnmektedir."],"answer":"A","solution":"Doğru cevap A seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Önce soru kökünü okuyup metindeki ilgili kanıtları belirleyiniz.","hint":"Seçenekleri metnin bütünüyle karşılaştırınız.","keepOptionOrder":true,"plainText":true,"collection":"grade8-lgs-deneme-expanded"},{"grade":8,"topic":"Parçada anlam","difficulty":"Orta","outcome":"Paragrafta anlam, yapı ve anlatım özelliklerini belirler.","text":"(I) Ülkemizin kuzeyinde yer alan Amasya Yeşilırmak Nehri kıyısında bulunur. (II) Amasya “Ferhat ile Şirin” aşkının geçtiği yer olarak bilinir. (III) Ferhat Şirin’e aşık olur ve Şirin’in babasının sarayına su getirmek için oradaki dağlardan tüneller kazar. (IV) Ferhat ile Şirin’in aşkı ile bilinen Amasya şehrimiz çekiciliğini ve doğal güzelliklerini hâlâ korumaktadır.","stem":"Bu parçada numaralanmış cümlelerden hangisi kanıtlanabilirlik açısından diğerlerinden farklıdır?","options":["I.","II.","III.","IV."],"answer":"D","solution":"Doğru cevap D seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Önce soru kökünü okuyup metindeki ilgili kanıtları belirleyiniz.","hint":"Seçenekleri metnin bütünüyle karşılaştırınız.","keepOptionOrder":true,"plainText":true,"collection":"grade8-lgs-deneme-expanded"},{"grade":8,"topic":"Parçada anlam","difficulty":"Orta","outcome":"Paragrafta anlam, yapı ve anlatım özelliklerini belirler.","text":"1) Hayran kaldığı oyuncağı alabilmek için para biriktiriyor.(Sebep-sonuç) 2) Uzun yolculuklardan hoşlanmadığı için uçakla seyahati tercih ediyor. (Sebep-sonuç) 3) Sağlıklı bir yaşam sürmek için öğünlerinizden tereyağını eksik etmeyin, dedi. (Amaçsonuç) 4) Girdiği bütün sınavlarda başarı gösterdiği için madalya aldı.(Amaç-sonuç","stem":"Numaralanmış cümlelerin hangisinde, ayraç içinde verilen anlam ilişkisi vardır?","options":["3 ve","2 ve","1 ve","1 ve"],"answer":"B","solution":"Doğru cevap B seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Önce soru kökünü okuyup metindeki ilgili kanıtları belirleyiniz.","hint":"Seçenekleri metnin bütünüyle karşılaştırınız.","keepOptionOrder":true,"plainText":true,"collection":"grade8-lgs-deneme-expanded"},{"grade":8,"topic":"Dil ve anlatım","difficulty":"Orta","outcome":"Paragrafta anlam, yapı ve anlatım özelliklerini belirler.","text":"Son yıllarda düğün davetiyelerinde zaman zaman şu ifadeleri görüyoruz. “Çocuklara iyi uykular.” Açık açık şunu söylüyorlar:”Sen gel, eşin gelsin, ama çocukların gelmesin.” Ne kadar medeni bir uygulama(!) değil mi? Ailelerin neşesi çocuklar düğünlerde dert oluyor birilerine demek ki. Kültürümüzü, örfümüzü, âdetlerimizi geleceğe taşıyacak bu çocuklar böyle yetişirse yakında davetiyelerde şu ifadeleri göreceğiz: “Çocuklara ve yaşlılara iyi uykular.”","stem":"Yukarıdaki parçanın dil ve anlatımı için hangisi söylenemez?","options":["Tanık gösterme kullanılmıştır.","Koşul sonuç cümlesi vardır.","İkilemeler kullanılmıştır.","Devrik cümle kullanılmıştır."],"answer":"A","solution":"Doğru cevap A seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Önce soru kökünü okuyup metindeki ilgili kanıtları belirleyiniz.","hint":"Seçenekleri metnin bütünüyle karşılaştırınız.","keepOptionOrder":true,"plainText":true,"collection":"grade8-lgs-deneme-expanded"},{"grade":8,"topic":"Yardımcı düşünce","difficulty":"Orta","outcome":"Paragrafta anlam, yapı ve anlatım özelliklerini belirler.","text":"Doğanın yükünü azaltmak için tüketim kültürünün değişimi ailede başlıyor. Her hanede gıda israfının azaltılması, daha az atık üretilmesi ve elektrik su gibi kaynakların kontrollü kullanılması gibi temel sorumluluklara karşı duyarlılık geliştirilmeli. Gıda israfı, beraberinde su, elektrik, yakıt gibi birçok kaynağın da israfı demek. Ülkemizde ne yazık ki gıda israfı da had safhalarda. Üretilen meyve ve sebzelerin %40'ı çöpe gidiyor. Eğer israf edilen gıdalar bir ülke olsaydı, dünyaya en çok karbon ayak izi bırakan ülke olacaktık. Evlerinize aldığınız gıda ürünlerini bozulmadan tüketmeye, hatta tabiri caiz ise kabuğundan çekirdeğine değerlendirmeye çalışın.","stem":"Bu parçadan aşağıdakilerden hangisi çıkarılamaz?","options":["Gıdaların israf edilmesi başka alanlardaki israfa da neden olmaktadır.","Doğayı koruyabilme adına verilmesi gereken eğitim ailede başlamalıdır.","Evlerimize alınan gıda ürünlerini her hâlükârda tüketmeliyiz.","Üretilen sebze ve meyvelerin yarıdan fazlası çöpe gitmemektedir."],"answer":"C","solution":"Doğru cevap C seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Önce soru kökünü okuyup metindeki ilgili kanıtları belirleyiniz.","hint":"Seçenekleri metnin bütünüyle karşılaştırınız.","keepOptionOrder":true,"plainText":true,"collection":"grade8-lgs-deneme-expanded"},{"grade":8,"topic":"Anlatım biçimleri","difficulty":"Orta","outcome":"Paragrafta anlam, yapı ve anlatım özelliklerini belirler.","text":"Bu ülkede kadın olmakla erkek olmak arasındaki ayrım doğdukları günden itibaren başlar. Erkek çocukları güçlü, kız çocukları sessiz olmak zorundadırlar. Çünkü ülkemizde erkeğe yüklenen görev güçlülük temelleri üzerine atılırken kız çocukları hanım hanımcık olmaları gerektiğine inanılarak yetiştirilir. Yetişen bu “güçlü” beylerimiz ilerde ola ki sesi çıkan bir kadına denk geldiklerinde o güçlü(!) yanlarını ortaya çıkarıverirler. O yüzdendir ki son yıllarda boşanmak isteyen, karısına şiddet uygulayan bir tür ortaya çıkmıştır. Oysa evladın cinsiyeti ne olursa olsun insanların duygularına, düşüncelerine saygı gösterebilen bireyler yetiştirmek biz ebeveynlerin görevidir. Bunu başardığımız zaman daha sağlıklı, huzurlu bir toplumu da ortaya çıkarmış oluruz.","stem":"Bu parçada aşağıdaki anlatım biçimlerinden hangisi ağır basmaktadır?","options":["Tartışma","Açıklama","Betimleme","Öyküleme"],"answer":"A","solution":"Doğru cevap A seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Önce soru kökünü okuyup metindeki ilgili kanıtları belirleyiniz.","hint":"Seçenekleri metnin bütünüyle karşılaştırınız.","keepOptionOrder":true,"plainText":true,"collection":"grade8-lgs-deneme-expanded"},{"grade":8,"topic":"Paragrafta sıralama","difficulty":"Orta","outcome":"Paragrafta anlam, yapı ve anlatım özelliklerini belirler.","text":"1. Dere kenarında yürüyüş yaparken gözünüzü derenin ve ortamın güzelliğinden ayırıp çakıl taşlarına bakın. 2. Örneğin; bir çakıl taşı yuvarlak bir şekle sahip değilseköşeleri fazlabu taş büyük olasılıkla yakın bir kayadan kopup gelmiş demektir. 3. Oysa biraz jeoloji bilgisine sahipseniz bu taşlar size çok fazla bilgi sunar. 4. Su onu önüne katıp çok fazla sürüklemediği için köşeli yapısını hâlâ korumaktadır. 5. Bu çakıllar size fazla bir şey anlatmayabilir.","stem":"Numaralanmış cümlelerden anlamlı bir paragraf oluşturulmak istendiğinde doğru sıralama nasıl olur?","options":["1-2-4-3-5","5-1-3-2-4","1-5-3-2-4","5-2-3-4-2"],"answer":"C","solution":"Doğru cevap C seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Önce soru kökünü okuyup metindeki ilgili kanıtları belirleyiniz.","hint":"Seçenekleri metnin bütünüyle karşılaştırınız.","keepOptionOrder":true,"plainText":true,"collection":"grade8-lgs-deneme-expanded"},{"grade":8,"topic":"Yardımcı düşünce","difficulty":"Orta","outcome":"Paragrafta anlam, yapı ve anlatım özelliklerini belirler.","text":"Günümüzde yazar ve şairlerimizin edebiyat ile ilişkilerinin değiştiğinin sanırım hepiniz farkındasınız. (I) Çünkü bugünkü yazar ya da şairlerimiz çalışma yapacakları masaya geçen yüzyıllardakiler gibi temiz bir zihinle oturmuyorlar. (II) Günümüzde edebi metinlerin kaynağı olarak görülen ve kendilerinden çok şey beklenen şair ve yazarlar yelkenlerini maalesef edebiyat denizinin dışında yüzdürmeye çalışıyorlar. (III) Onların aklının bir köşesinde daima yakın zamanlarda piyasaya çıkacak olan eserlerinin ne kadar basılıp satılacağı ya da televizyon programlarında nasıl boy gösterecekleri var. (IV) Böyle bir zihin ve kalp kıskacının arasında şekillenmeye çalışan edebiyat ise bu olaylardan en olumsuz etkilenen oluyor.","stem":"Yukarıdaki paragrafta numaralanmış cümleler adına aşağıdakilerden hangisi söylenemez?","options":["I. cümlede bugünkü yazarlarla geçmiştekiler arasındaki fark söylenmiştir.","II. cümlede yazarların günümüzde edebiyat dünyasının dışında kaldıkları söylenmiştir.","III. cümlede günümüz yazarlarının amacının ne olduğu hakkında bilgi verilmiştir.","IV. cümlede insanların bu değişen edebiyat anlayışından en çok etkilenenler olduğu söyleniyor."],"answer":"D","solution":"Doğru cevap D seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Önce soru kökünü okuyup metindeki ilgili kanıtları belirleyiniz.","hint":"Seçenekleri metnin bütünüyle karşılaştırınız.","keepOptionOrder":true,"plainText":true,"collection":"grade8-lgs-deneme-expanded"},{"grade":8,"topic":"Parçada anlam","difficulty":"Orta","outcome":"Paragrafta anlam, yapı ve anlatım özelliklerini belirler.","text":"Yıldız Dağları’nı döne döne tırmanıyorduk. Güneş sabahın o sisli havasının etkisiyle az buçuk görünen tepelerin arkasından doğuyordu. Güneşin henüz ulaşamadığı yamacın kenarlarında ise derin bir sessizlik hâkimdi. Derken yeşilin en güzel tonlarıyla bezeli çarşaf gibi yaylaların arasından bir araba göründü. Arabanın gelişinden üzerinde yılların yorgunluğunu taşıdığı belliydi. Arabaya dikkatlice baktığımızda oradan bize el sallayan birilerinin olduğunun farkına vardık. Güneş etkisini yavaşça göstermeye başlayınca bu gelenlerin bir grup dağcı olduğunun farkına vardık. Yukarıdaki paragrafta kullanılan yazın türü","stem":"aşağıdakilerden hangisidir?","options":["Hikâye","Gezi yazısı","Masal","Roman"],"answer":"B","solution":"Doğru cevap B seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Önce soru kökünü okuyup metindeki ilgili kanıtları belirleyiniz.","hint":"Seçenekleri metnin bütünüyle karşılaştırınız.","keepOptionOrder":true,"plainText":true,"collection":"grade8-lgs-deneme-expanded"},{"grade":8,"topic":"Metin türleri","difficulty":"Orta","outcome":"Paragrafta anlam, yapı ve anlatım özelliklerini belirler.","text":"‘’Kitaptan niçin korkarlar? Bunu bir türlü anlayamadım. Kitaptan korkmak, insan düşüncesinden korkmak, insanı kabul etmemektir. Kitaptan korkan adam, insanı mesuliyet hissinden mahrum ediyor demektir. \"Bırak, senin yerine ben düşünüyorum!\" demekle, \"Falan kitabı okuma!\" demek arasında hiçbir fark yoktur. İnsanoğlu her şeyden evvel mesuliyet hissidir ve bilhassa fikirlerin mesuliyetidir. Ondan mahrum edilen insan, kendiliğinden bir paçavra hâline dönüşür. Şüphesiz insanı korumamız lâzım gelen vaziyetler vardır. Fakat bu vaziyetler daha ziyade ferdin kendi dışındaki vaziyetlerdir. Bir insanı kendi içinde, düşüncesinin mahremiyetinden korumaya hakkımız yoktur. Ortaçağ'dan bugüne kadar gelen zaman içinde insanlığın belki en büyük kazancı bu basit hakikati kendisine mal etmesidir.’’","stem":"Yukarıdaki metin aşağıdaki yazı türlerinin hangisinden alınmış olabilir?","options":["Eleştiri","Deneme","Sohbet","Fıkra"],"answer":"B","solution":"Doğru cevap B seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Önce soru kökünü okuyup metindeki ilgili kanıtları belirleyiniz.","hint":"Seçenekleri metnin bütünüyle karşılaştırınız.","keepOptionOrder":true,"plainText":true,"collection":"grade8-lgs-deneme-expanded"},{"grade":8,"topic":"Parçada anlam","difficulty":"Orta","outcome":"Paragrafta anlam, yapı ve anlatım özelliklerini belirler.","text":"Eğitsel değer taşıyan filmler, bizde çok ilgi görmez. Bu yüzden olacak dünyanın en fazla film yapan uluslarından biri olduğumuz halde ciddi konulu filmlerimizin sayısı çok azdır. Bizdeki filmler insanı iki eyleme götürür: Ya gülme ya ağlama. Buna rağmen düşündürme, duygularını zenginleştirip seyirciyi eğitme… İşte bunun gibi şeyler yok bizim filmlerimizde.","stem":"Bu parçada, yazarın yakındığı durum aşağıdakilerden hangisidir?","options":["Sinema filmlerinin eğitici nitelikte olmamasından","Daha çok komedi ve dram türü filmlerin yapılmasından","Bizim sinemamızın diğer ülkelerden geri kalmasından","Kendi hayatımızı yansıtan orijinal senaryolara sahip olmamamızdan"],"answer":"A","solution":"Doğru cevap A seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Önce soru kökünü okuyup metindeki ilgili kanıtları belirleyiniz.","hint":"Seçenekleri metnin bütünüyle karşılaştırınız.","keepOptionOrder":true,"plainText":true,"collection":"grade8-lgs-deneme-expanded"},{"grade":8,"topic":"Dil ve anlatım","difficulty":"Orta","outcome":"Paragrafta anlam, yapı ve anlatım özelliklerini belirler.","text":"Gün geldi halkla aram tahmin bile edemeyeceğiniz şekilde açıldı. Öyle lokantalarda yemek yedim ki bir öğlen yemeği parasına beş kişi bir hafta doyardı. Etrafımda lavanta kokan insanlar vardı. Herkes ve her şey pırıl pırıldı. Ama neden ruhumun derinliklerinde her zaman küçük, mütevazı köşeler aradım, dostlarımı, en sevdiklerimi bu çarşı içlerinin kara çocuklarından seçtim, bir tezgâhta halı dokuyan narin bir kızı sevdim, keçi kokusu sarmış ağıllarda çobanlarla oturdum, köylülerle beraber demir parmaklıklara asılıp belediye bahçesinin içinden saz dinledim? Bu ve bunun gibi çelişkilerin cevabını da biliyordum aslında. Belki de bildiklerimi kendime söylemeye çekiniyordum.","stem":"Bu parçanın anlatımıyla ilgili olarak aşağıdakilerden hangisi söylenemez?","options":["Niteleyici sözcüklere yer verilmiştir","Benzetmeye yer verilmiştir.","Deyim kullanılmıştır.","Karşılaştırma yapılmıştır."],"answer":"B","solution":"Doğru cevap B seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Önce soru kökünü okuyup metindeki ilgili kanıtları belirleyiniz.","hint":"Seçenekleri metnin bütünüyle karşılaştırınız.","keepOptionOrder":true,"plainText":true,"collection":"grade8-lgs-deneme-expanded"},{"grade":8,"topic":"Parçada anlam","difficulty":"Orta","outcome":"Paragrafta anlam, yapı ve anlatım özelliklerini belirler.","text":"(I) Sağlık çalışanlarına yönelik şiddetin arttığı bugünlerde, hastaların yanı sıra hastane çalışanlarının sahip olduğu haklar zaman zaman yazılı ve görsel basında yer alıyor. (II) Çeşitli sebeplerden yaşanan ve kimi zaman fiziksel şiddete varan, son derece vahim ve üzücü olaylar bu hakların karşılıklı olarak ihlâl edilmesinden kaynaklanabiliyor. (III) Hasta olan kişinin ruhsal, duygusal ve psikolojik açıdan oldukça hassas olduğu düşünülürse hastanelerdeki danışma ve yönlendirme birimlerine onları sakinleştirmek, rahatlatmak ve hastaların işini kolaylaştırmak adına çok önemli görev düşüyor. (IV) Sağlık sisteminin düzenli olarak işleyebilmesi için hasta ile sağlık personelinin iletişiminin saygı, anlayış ve duygudaşlık esasına dayanması gerektiğine inanıyorum.","stem":"Bu metindeki numaralanmış cümlelerden hangisi kişisel görüş içermemektedir?","options":["I.","II.","III.","IV."],"answer":"A","solution":"Doğru cevap A seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Önce soru kökünü okuyup metindeki ilgili kanıtları belirleyiniz.","hint":"Seçenekleri metnin bütünüyle karşılaştırınız.","keepOptionOrder":true,"plainText":true,"collection":"grade8-lgs-deneme-expanded"},{"grade":8,"topic":"Yardımcı düşünce","difficulty":"Orta","outcome":"Paragrafta anlam, yapı ve anlatım özelliklerini belirler.","text":"Ballıbabagiller familyasından olan kekik; güneşli yerleri seven, genellikle çorak topraklarda yetişen çok yıllık bir bitkidir. Boyları 15 - 40 cm arasındadır. Yaprakları karşılıklı, bir sonraki ile ters, oval, eliptik veya yumurta şeklinde, koyu yeşil renkli, sapsız veya kısa saplıdır. Çiçekleri geriye doğru çan şeklinde, pembe, pembemsi kırmızı, eflatun veya pembemsi beyaz renktedir. Kekik; ilk çağlardan itbaren ilaç, gıda, içecek, tekstil, boya, parfümeri ve kozmetik gibi farklı alanlarda kullanılmaktadır. Ülkemizde en çok Doğu ve Güneydoğu Anadolu Bölgesi’nde yetişen kekiğin birçok hastalığa iyi geldiği yüzyıllardır bilinmektedir. Hem taze hem de kuru olarak kullanılabilen kekik, lezzeti ile de dünya ve Türk mutfaklarının vazgeçilmezlerindendir.","stem":"Bu metinde kekikle ilgili aşağıdakilerden hangisine değinilmemiştir?","options":["Ülkemizde yetiştiği yerlere","Hangi hastalıklara iyi geldiğine","Yaprak ve çiçeklerinin özelliklerine","Hangi alanlarda kullanıldığına"],"answer":"B","solution":"Doğru cevap B seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Önce soru kökünü okuyup metindeki ilgili kanıtları belirleyiniz.","hint":"Seçenekleri metnin bütünüyle karşılaştırınız.","keepOptionOrder":true,"plainText":true,"collection":"grade8-lgs-deneme-expanded"},{"grade":8,"topic":"Parçada anlam","difficulty":"Orta","outcome":"Paragrafta anlam, yapı ve anlatım özelliklerini belirler.","text":"Çoğu zaman güzel resimlenmiş, tasarımına ve kâğıt seçimine biraz özenilmiş çocuk kitaplarına baksam genellikle: “Neden yetişkinler için böyle kitaplar hazırlanmıyor?” sorusu aklıma gelirdi. Aslında yayımlanmadı sayılmaz ama hep dağınık kaldı ve düzenli bir seri olmadı. Sonuçta her iyi çizer, iyi bir resimleyici değildir. Çünkü bu, özellikle edebiyat konusundaysa çizginin metinle anlatılanı ikna etmeye yönelik olmasıyla gerçekleşir. Ana unsur olan çizgi, asıl amaca böyle hizmet eder.","stem":"Bu parçadan aşağıdakilerden hangisine ulaşamayız?","options":["Çocuk kitaplarının bazılarının güzel resimlendiğine","Her çizerin iyi bir resimleyici olmadığına","Kitaptaki çizgili anlatımın anlatılanı inandırıcı kılmaya yöneldiğine","Büyükler için resimli kitaplar yayımlanmadığına"],"answer":"D","solution":"Doğru cevap D seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Önce soru kökünü okuyup metindeki ilgili kanıtları belirleyiniz.","hint":"Seçenekleri metnin bütünüyle karşılaştırınız.","keepOptionOrder":true,"plainText":true,"collection":"grade8-lgs-deneme-expanded"},{"grade":8,"topic":"Parçada anlam","difficulty":"Orta","outcome":"Paragrafta anlam, yapı ve anlatım özelliklerini belirler.","text":"Türk seyirlik oyunlarından biridir Karagöz. Karagöz’ün tiyatromuzda artık yeri ve etkisi kalmadı, deniyor. Oysa Karagöz, 14. yüzyıldan beri kendini sürekli yenileyerek bugünlere gelmiştir. Güzel sanatlara ait ne varsa hepsi bir gölge oyunu olan Karagöz’de de vardır.","stem":"Bu parçadan “Karagöz oyunu” ile ilgili çıkarılabilecek en kapsamlı yargı aşağıdakilerden hangisidir?","options":["Köklü bir geçmişe sahip olan Karagöz güzel sanatları da içermektedir.","Karagöz bütün dünyada hâlâ seyredilen bir oyundur.","Yüzyıllardır yaşayan Karagöz oyunu ileride de unutulmayacaktır.","Seyir sanatlarımızda en eski gölge oyunu Karagöz’dür."],"answer":"A","solution":"Doğru cevap A seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Önce soru kökünü okuyup metindeki ilgili kanıtları belirleyiniz.","hint":"Seçenekleri metnin bütünüyle karşılaştırınız.","keepOptionOrder":true,"plainText":true,"collection":"grade8-lgs-deneme-expanded"},{"grade":8,"topic":"Parçada anlam","difficulty":"Orta","outcome":"Paragrafta anlam, yapı ve anlatım özelliklerini belirler.","text":"Son yıllarda yayımlanan öykü kitaplarına bakıyorum. Hemen hepsi birbirine benziyor. Sanki bir kişi yazmış ve onun benzerlerini de başkaları çoğaltmış. Oysa öykü ya da başka türde yazılanlar birbirine benzememeli, birbirinden çok farklı olmalı. Bu olursa daha kaliteli öyküler ortaya çıkar, onları okuyanlara da o kitap katkı yapar. Genç yazarlarımız bu konuda duyarlı olmalı, ustaların izinden gitmeli ama onlardan farklı yazmalılar.","stem":"Bu parçadan aşağıdakilerden hangisini çıkaramayız?","options":["Bu aralar yayımlanan öykülerin birbirine benzediğini","Usta öykücülerin izinden gidenlerin başarılı eserler oluşturduğunu","Gerçek öykünün başkalarına benzememesi gerektiğini","Genç yazarların ustaların izinden giderken onlardan farklı yazmaları gerektiğini"],"answer":"B","solution":"Doğru cevap B seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Önce soru kökünü okuyup metindeki ilgili kanıtları belirleyiniz.","hint":"Seçenekleri metnin bütünüyle karşılaştırınız.","keepOptionOrder":true,"plainText":true,"collection":"grade8-lgs-deneme-expanded"},{"grade":8,"topic":"Parçada anlam","difficulty":"Orta","outcome":"Paragrafta anlam, yapı ve anlatım özelliklerini belirler.","text":"Bir cümleden yorum ve çıkarımlar sonucu edindiğimiz ikinci bir anlama örtülü anlam denir. Örtülü anlama gizli anlam da diyebiliriz çünkü ilk bakışta görünmez. Onu açığa çıkarmak için cümleyi yorumlamak gerekir. “Toplantıya Ali de geldi.” cümlesini yorumladığımızda toplantıda Ali'den başka kişilerin de olduğunu ortaya çıkarırız ve bu cümledeki örtülü yani gizli anlamı bulmuş oluruz. Daha sade ve daha mutlu bir hayat yaşıyorum artık. Kıskanmıyorum artık zengin insanların malını mülkünü. Bir simit, bir poğaça. Çayımı da içiyorum yanında. Oh ne ala! Onların olsun bütün zenginlikler. Onların olsun hayatın çilesi, keşmekeşi, sahtelikleri. Ben mutluyum cebimdeki bozuk paraların şıngırtısından, dişimin arasında kalan simit susamlarından. Hayattan zevk alınabileceğini anladım sonunda.","stem":"Buna göre aşağıdaki cümlelerden hangisi bu parçadan çıkarılabilecek bir örtülü anlam değildir?","options":["Önceden pek mutlu bir hayat sürmüyordum.","Zengin insanların malını ve mülkünü kıskanırdım.","Önceden hayattan zevk alınabileceğini bilmezdim.","Önceden çay ve simitten pek hoşlanmazdım."],"answer":"D","solution":"Doğru cevap D seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Önce soru kökünü okuyup metindeki ilgili kanıtları belirleyiniz.","hint":"Seçenekleri metnin bütünüyle karşılaştırınız.","keepOptionOrder":true,"plainText":true,"collection":"grade8-lgs-deneme-expanded"}];
